#[test]
fn html_pre_wrap_of_query_titles_matches_ncbi() {
    for (title, expected) in WRAP_CASES {
        let mut out = Vec::new();
        write_html_wrapped(&mut out, title, 68).unwrap();
        assert_eq!(
            String::from_utf8_lossy(&out),
            String::from_utf8_lossy(expected),
            "title {}",
            String::from_utf8_lossy(&title[..4])
        );
    }
}

#[test]
fn html_encode_is_ncbis_encode_all() {
    // htmlhelper.cpp:58-130: `"`, `&`, `<`, `>` encoded; `'` and an existing entity's `&` too.
    assert_eq!(
        html_encode(b"a&b<c>d\"e'f &amp; \xc3\xbc"),
        b"a&amp;b&lt;c&gt;d&quot;e'f &amp;amp; \xc3\xbc".to_vec()
    );
    assert_eq!(html_encode(b""), b"".to_vec());
}

#[test]
fn html_pre_wrap_keeps_backspaces_as_ncbi() {
    // ncbistr.cpp:5250-5257, 5277-5301: a backspace eats the byte before it.
    let mut out = Vec::new();
    wrap_html_pre(b"ab\x08c", 68, &mut out);
    assert_eq!(out, b"ac\n".to_vec());
}
